cd /app && python3 - <<'EOF'
import json,subprocess
s=json.load(open('/tmp/seqs.json')); i=s['input'].upper()
def rc(x): return x.translate(str.maketrans("ACGT","TGCA"))[::-1]
def tm(x):
    return float(subprocess.run(["oligotm","-tp","1","-sc","1","-mv","50","-dv","2","-n","0.8","-d","500",x],capture_output=True,text=True).stdout)
pos=215
for lr in range(30,46):
    print(lr, round(tm(rc(i[pos-lr:pos])),2))
for lf in range(15,26):
    print('F',lf, round(tm(i[pos:pos+lf]),2))
EOF

